/**
 * The Worker entry point Cloudflare runs.
 *
 * `npm run build` (adapter-cloudflare) writes the SvelteKit app to
 * .svelte-kit/cloudflare/_worker.js. This file wraps it to add what a
 * SvelteKit build cannot export by itself:
 *
 *   - the Durable Object classes (chat live delivery, shared key-value store)
 *   - the cron handler, which replaces the setInterval background jobs the
 *     Node server used to run (see src/routes/api/internal/cron/+server.ts)
 */
// @ts-expect-error generated by the build
import app from '../.svelte-kit/cloudflare/_worker.js';

export { ChatHub } from './chat-hub';
export { KvStore } from './kv-store';

interface Env {
	ORIGIN?: string;
	[key: string]: unknown;
}

export default {
	fetch: app.fetch,

	async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
		const origin = (env.ORIGIN || 'https://champ-hr.com').replace(/\/+$/, '');
		const url = `${origin}/api/internal/cron?t=${controller.scheduledTime}`;
		// `__CRON` only exists on this in-process call; a request from the
		// internet can never carry it, so the route needs no shared secret.
		const res: Response = await app.fetch(new Request(url, { method: 'POST' }), { ...env, __CRON: true }, ctx);
		if (!res.ok) console.error(`[cron] ${res.status}: ${(await res.text()).slice(0, 500)}`);
	}
} satisfies ExportedHandler<Env>;
